from pathlib import Path
import json, html, re
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'site'
OUT.mkdir(exist_ok=True)
def esc(s): return html.escape(str(s),quote=True)
def link(url,label,cls=''): return f'<a class="{cls}" href="{esc(url)}">{label}</a>'
DATA=json.loads((ROOT/'content/site.json').read_text())
GROUPS=DATA['research']
PAPERS=DATA['papers']
def heading(k,title,desc=''):
 return f'<div class="section-heading"><div><p class="eyebrow">{k}</p><h2>{title}</h2></div>{f"<p>{desc}</p>" if desc else ""}</div>'
def papers(items):
 return ''.join(f'''<article class="paper"><div class="paper-meta"><span class="venue">{esc(p['venue'])}</span><span>{p['year']}</span></div><div><h3>{link(p['url'],esc(p['title']))}</h3><p class="authors">{esc(p['authors'])}</p><p>{esc(p['summary'])}</p><div class="paper-links">{link(p['url'],'论文 ↗')}{link(p['code'],'代码 ↗') if p.get('code') else ''}<span>{esc(next(g['short'] for g in GROUPS if g['id']==p['area']))}</span></div></div></article>''' for p in items)
def groupcards():
 return ''.join(f'<a class="research-card" href="research.html#{g["id"]}"><span class="index">0{i+1}</span><h3>{g["title"]}</h3><p>{g["summary"]}</p><span class="card-bottom">{g["en"]}<span aria-hidden="true">↗</span></span></a>' for i,g in enumerate(GROUPS))
def person():
 return '''<article class="pi"><img src="assets/weiwei-lin.jpg" alt="林伟伟教授" width="160" height="160"><div><p class="eyebrow">TEAM LEAD / 团队负责人</p><h2>林伟伟 <span>Weiwei Lin</span></h2><p class="pi-role">教授 · 博士生导师</p><p>华南理工大学计算机科学与工程学院教授，先进计算体系结构团队负责人，鹏城实验室双聘研究员，CCF 杰出会员、IEEE 高级会员。</p><p>研究聚焦云计算调度与节能、算力能效优化、大模型与边缘智能，以及时序预测。2021—2025 年连续入选斯坦福大学全球前 2% 顶尖科学家榜单。</p><div class="paper-links"><a href="https://www.scholat.com/linweiwei">个人主页 ↗</a><a href="https://scholar.google.com/citations?user=IWsha94AAAAJ">Google Scholar ↗</a><a href="mailto:linww@scut.edu.cn">联系老师 ↗</a></div></div></article>'''
def shell(title,active,body):
 nav=[('index.html','首页','home'),('research.html','研究方向','research'),('people.html','团队成员','people'),('publications.html','论文成果','publications')]
 menu=''.join(f'<a href="{u}" {"aria-current=page" if active==a else ""}>{l}</a>' for u,l,a in nav)
 return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#102e50"><title>{title} · ACAT @ SCUT</title><meta name="description" content="华南理工大学先进计算体系结构团队（ACAT）：云计算与绿色计算、算力调度、大模型、时间序列与边缘智能。了解团队成员、研究成果和开源项目。"><link rel="canonical" href="https://acat-scut.github.io/{'' if active=='home' else active+'.html'}"><link rel="icon" href="assets/acat-logo.png"><link rel="stylesheet" href="styles.css"><script src="script.js" defer></script><noscript><style>@media(max-width:860px){{.site-header{{height:auto;position:relative}}.header-inner{{flex-wrap:wrap;padding-top:15px;padding-bottom:15px}}nav{{display:flex;position:static;box-shadow:none;padding:0;width:100%;flex-direction:row;flex-wrap:wrap;gap:10px 20px}}.menu-toggle{{display:none}}}}</style></noscript></head><body><a class="skip-link" href="#main">跳到正文</a><header class="site-header"><div class="container header-inner"><a class="brand" href="index.html"><img src="assets/acat-logo.png" width="48" height="48" alt="ACAT 团队标志"><span><strong>ACAT <b>@ SCUT</b></strong><small>先进计算体系结构团队</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav">菜单 <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="主导航">{menu}<a href="index.html#join">加入我们</a><a class="github-link" href="https://github.com/ACAT-SCUT">GitHub ↗</a></nav></div></header><main id="main">{body}</main><footer><div class="container footer-main"><div><a class="footer-brand" href="index.html">ACAT <span>@ SCUT</span></a><p>先进计算体系结构团队<br>华南理工大学 · 计算机科学与工程学院</p></div><div><h3>探索</h3><a href="research.html">研究方向</a><a href="people.html">团队成员</a><a href="publications.html">论文成果</a></div><div><h3>联系与链接</h3><a href="mailto:linww@scut.edu.cn">linww@scut.edu.cn</a><a href="https://www2.scut.edu.cn/cs/">学院主页 ↗</a><a href="https://github.com/ACAT-SCUT">GitHub 组织 ↗</a></div></div><div class="container footer-bottom"><span>© 2026 ACAT @ SCUT</span><span>公开资料整理于 2026.09.12 · <a href="sources.html">资料来源</a></span></div></footer></body></html>'''
hero='''<section class="hero"><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow">SOUTH CHINA UNIVERSITY OF TECHNOLOGY</p><h1>先进计算<span>让智能更高效。</span></h1><p class="hero-en">Advanced Computing Architecture Team</p><p class="hero-description">从云端算力到边缘智能，从系统优化到大模型，<br class="desktop-break">探索高效、智能、可持续的计算。</p><div class="hero-actions"><a class="button button-white" href="research.html">探索我们的研究 <span>↗</span></a><a class="text-link" href="publications.html">阅读论文成果 ↗</a></div><div class="hero-affiliation"><span>华南理工大学</span><span>计算机科学与工程学院</span></div></div><div class="research-map"><p class="map-label">OUR RESEARCH / 研究版图</p>'''+''.join(f'<a href="research.html#{g["id"]}"><span>0{i+1}</span><div>{g["short"]}<small>{g["en"]}</small></div><b aria-hidden="true">↗</b></a>' for i,g in enumerate(GROUPS))+'''</div></div></section>'''
intro='''<section class="intro-band"><div class="container intro-grid"><p class="eyebrow">ABOUT THE TEAM</p><div><h2>面向真实世界的计算挑战</h2><p>先进计算体系结构团队立足华南理工大学，其前身可追溯至 2005 年成立的计算机系统结构研究所。我们连接计算系统与智能算法，研究从数据中心、异构集群到边缘设备的计算效率问题，并通过开放代码推动研究复现与应用。</p></div><a class="inline-link" href="people.html">认识团队 ↗</a></div></section>'''
news='<section class="section container">'+heading('RESEARCH HIGHLIGHTS','近期研究进展','从计算基础设施到智能模型，持续推进系统与算法的协同创新。')+'<div class="highlights">'+''.join(f'<a href="{p["url"]}" class="highlight"><span class="eyebrow">{p["venue"]} / {p["year"]}</span><h3>{p["name"]}</h3><p>{p["summary"]}</p><span class="inline-link">了解研究 ↗</span></a>' for p in [PAPERS[0],PAPERS[1],PAPERS[2]])+'</div></section>'
join='''<section class="join" id="join"><div class="container join-grid"><div><p class="eyebrow">CONNECT WITH ACAT</p><h2>一起探索计算的下一步。</h2><p>对我们的研究感兴趣？欢迎围绕研究生学习、学术交流与科研合作联系团队。</p><a class="button button-white" href="mailto:linww@scut.edu.cn">联系林伟伟老师 ↗</a></div><div class="contact-details"><h3>华南理工大学 · 广州</h3><p>大学城校区 · 计算机科学与工程学院 B3 栋</p><a href="mailto:linww@scut.edu.cn">linww@scut.edu.cn</a><p class="contact-note">招生要求、名额与时间安排，以学校及导师最新通知为准。</p><a href="https://yz.scut.edu.cn/">研究生招生信息 ↗</a></div></div></section>'''
home=hero+intro+news+'<section class="section muted"><div class="container">'+heading('RESEARCH AREAS','五个方向，共同的计算愿景')+'<div class="research-grid">'+groupcards()+'</div></div></section><section class="section container">'+person()+'</section><section class="section soft"><div class="container">'+heading('SELECTED PUBLICATIONS','代表论文')+papers([PAPERS[3],PAPERS[4],PAPERS[5]])+'<a class="button button-outline" href="publications.html">查看全部精选论文 ↗</a></div></section>'+join
(OUT/'index.html').write_text(shell('先进计算体系结构团队','home',home))
def pagehead(en,title,desc): return f'<section class="page-head"><div class="container"><p class="eyebrow">{en}</p><h1>{title}</h1><p>{desc}</p></div></section>'
research=pagehead('RESEARCH','让系统与智能算法共同进步','围绕计算资源、模型效率和应用需求，开展五个方向的研究。')+'<div class="container research-details">'
for i,g in enumerate(GROUPS):
 research+=f'<section class="research-detail" id="{g["id"]}"><div><span class="index">0{i+1}</span><p class="eyebrow">{g["en"]}</p><h2>{g["title"]}</h2></div><div><p class="lead">{g["summary"]}</p><ul class="topics">'+''.join(f'<li>{esc(t)}</li>' for t in g['topics'])+f'</ul><a class="inline-link" href="{g["source"]}">研究资料与学习资源 ↗</a><div class="related"><h3>相关成果</h3>'+''.join(f'<a href="{p["url"]}"><span>{p["name"]}</span><small>{p["venue"]} · {p["year"]}</small></a>' for p in PAPERS if p['area']==g['id'])+'</div></div></section>'
research+='</div><section class="section soft"><div class="container">'+heading('PROJECTS & COLLABORATION','科研项目','林伟伟教授公开主页列出的部分项目。')+'<div class="project-row"><time>2025.05—2028.04</time><div><h3>异构算力系统能效模型及仿真系统研究</h3><p>山东联合基金项目</p></div></div><div class="project-row"><time>2025.03—2028.02</time><div><h3>面向智算中心的 AI 算力综合管理平台及关键技术研究与应用示范</h3><p>广西重点研发项目</p></div></div><div class="project-row"><time>2025.09—2026.04</time><div><h3>AI 集群中的作业优先级调度和碎片整理</h3><p>华为云合作项目</p></div></div><a class="inline-link" href="https://www.scholat.com/linweiwei">更多项目与合作信息 ↗</a></div></section>' 
(OUT/'research.html').write_text(shell('研究方向','research',research))
people=pagehead('PEOPLE','以共同的好奇心，探索计算。','来自计算系统、机器学习与应用研究的团队。')+'<section class="section container">'+person()+'</section><section class="section soft"><div class="container">'+heading('RESEARCH COMMUNITY','研究成员','按团队公开资料中的研究方向整理；成员身份与毕业去向以个人主页为准。')
for g in GROUPS:
 people+=f'<section class="member-group"><h3>{g["title"]}</h3><div class="member-list">'+''.join(link(p['url'],esc(p['name'])+' <span aria-hidden="true">↗</span>','member') if p.get('url') else f'<span class="member">{esc(p["name"])}</span>' for p in g['people'])+'</div></section>'
people+='</div></section><section class="section container">'+heading('RECOGNITION','学术与应用','以下为林伟伟教授公开主页所列荣誉与成果。')+'<div class="highlights"><article class="highlight"><p class="eyebrow">2020</p><h3>科技进步奖</h3><p>“云计算调度优化技术”获广东省科技进步奖二等奖，林伟伟教授排名第一。</p></article><article class="highlight"><p class="eyebrow">2023 / 2024</p><h3>创新大赛金奖</h3><p>作为第一指导老师，指导学生两次获得中国国际大学生创新大赛产业命题赛道总决赛金奖。</p></article><article class="highlight"><p class="eyebrow">GB 43630-2023</p><h3>国家标准</h3><p>参与制定《塔式和机架式服务器能效限定值及能效等级》。</p></article></div><a class="inline-link" href="https://www.scholat.com/linweiwei">查看导师原始介绍 ↗</a></section>' 
(OUT/'people.html').write_text(shell('团队成员','people',people))
pubs=pagehead('PUBLICATIONS','论文与开放研究','精选近年代表成果。每篇论文保留原始论文或作者来源，开源项目可直接访问。')+'<section class="section container"><div class="publication-note">覆盖绿色计算、算力调度、大模型、时间序列与边缘智能。以下为精选列表，完整成果可查阅 <a href="https://scholar.google.com/citations?user=IWsha94AAAAJ">Google Scholar ↗</a>。</div>'
for year in sorted({p['year'] for p in PAPERS},reverse=True):
 pubs+=f'<section class="year-group"><h2>{year}</h2><div>'+papers([p for p in PAPERS if p['year']==year])+'</div></section>'
pubs+='</section>'
(OUT/'publications.html').write_text(shell('论文成果','publications',pubs))
sources=pagehead('SOURCES & EDITORIAL NOTES','资料来源','内容核实日期：2026 年 9 月 12 日。')+'<section class="section container prose"><h2>内容依据</h2><p>团队介绍及研究成员以实验室公开组织资料为基础，导师信息参考本人主页，论文优先使用出版方、作者论文与项目仓库。这里列出核实入口，方便进一步阅读。</p><ul>'+''.join(f'<li>{link(x["url"],esc(x["name"]))}<p>{esc(x["note"])}</p></li>' for x in DATA['sources'])+'</ul><h2>内容说明</h2><p>本网站收录的是精选成果，不代表团队完整论文目录。预印本年份、在线发表年份与正式卷期年份可能不同，论文页面标注以所链接来源为准。旧介绍中的在读人数、教授人数、引用量等动态统计未直接沿用。</p><p>成员分组依据组织公开目录，不对当前在读身份或毕业去向作推断。未能核实完整教师名录，因此仅单独展示公开确认的团队负责人。招生计划以学校及导师通知为准。</p></section>'
(OUT/'sources.html').write_text(shell('资料来源','sources',sources))
(OUT/'404.html').write_text(shell('页面未找到','404',pagehead('404','这个页面暂时不在这里。','你可以返回首页，继续了解我们的研究。')+'<section class="container section"><a class="button button-outline" href="/">返回首页</a></section>'))
(OUT/'.nojekyll').touch()
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://acat-scut.github.io/sitemap.xml\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://acat-scut.github.io/{f}</loc><lastmod>2026-09-12</lastmod></url>' for f in ['','research.html','people.html','publications.html','sources.html'])+'</urlset>')
